-- 1. Tạo Schema dm (Danh mục) nếu chưa có
IF NOT EXISTS (SELECT * FROM sys.schemas WHERE name = N'dm')
BEGIN
    EXEC('CREATE SCHEMA dm');
END
GO

IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dm].[benh_vien]') AND type in (N'U'))
BEGIN
    CREATE TABLE dm.benh_vien (        
        id bigint IDENTITY(1,1) PRIMARY KEY,
        ma varchar(10) not null UNIQUE, -- Chuẩn xác 10 ký tự (Giống HospitalCode)
        ten nvarchar(250), -- Tên bệnh viện
        
       -- Phân cấp hành chính & Địa bàn
        --91352 Trạm y tế phường An Thới Kiên Giang sáp nhập vào An Giang: CategoryAdministrativeAreaId kiên giang (91), CategoryAdministrativeAreaProvinceId An Giang
        ma_tinh_bv SMALLINT NOT NULL,                  -- CategoryAdministrativeAreaId    =91 (mã tỉnh cấu thành tên bv)
        ma_tinh SMALLINT NULL,                              -- CategoryAdministrativeAreaProvinceId =89 (bv thuộc quản lý của tỉnh nào)
        dia_chi NVARCHAR(250) NULL,                               -- Address
    
        -- Phân loại tuyến & hạng bệnh viện
        tuyen_bv SMALLINT NOT NULL,                        -- CategoryHospitalLineId
        hang_bv SMALLINT NULL,                             -- CategoryHospitalLevelId
        loai_bv TINYINT NOT NULL,                          -- HospitalType
        khoi_bv NVARCHAR(150) NULL,                             -- MedicalBlocks
        -- Cấu trúc phân cấp hệ thống bệnh viện (Cha - Con)
        ma_cha VARCHAR(10) NULL,                        -- Chuẩn xác 10 ký tự (Giống HospitalParentCode)
    
       -- Trạng thái hợp đồng, thanh toán, quản lý
       loai_hop_dong TINYINT NULL,                               -- ContractType
       loai_thanh_ly TINYINT NULL,                               -- LiquidateType
       resident_type TINYINT NULL,                                 -- ResidentType
       trang_thai_kcb TINYINT NULL,                            -- IsAllowed--dược khám hay không
    
        -- Cờ trạng thái & Thông tin bổ sung
        is_bv_quan_doi BIT NULL,                          -- IsModHospital (BV Quân đội hay không)
        article VARCHAR(1) NULL,                         -- Article
        ghi_chu NVARCHAR(255) NULL,                               -- Note
        trang_thai BIT NOT NULL DEFAULT 1,                        -- Status (1: Hoạt động, 0: Ngừng)  
        -- Quản lý dữ liệu hệ thống (Audit Fields)
        [created_at]                DATETIMEOFFSET NOT NULL DEFAULT SYSDATETIMEOFFSET(),
        [created_by]                int NULL,                              -- ID người tạo
        [updated_at]                DATETIMEOFFSET NULL,                      -- Thời điểm sửa
        [updated_by]                int NULL,                              -- ID người sửa
        [deleted_at]                DATETIMEOFFSET NULL,                      -- Thời điểm xóa mềm
        [deleted_by]                int NULL,                              -- ID người xóa mềm
        [is_deleted]                BIT NOT NULL DEFAULT 0                   -- 0: Dùng, 1: Xóa mềm                
    );
END
GO
SET IDENTITY_INSERT dm.benh_vien ON;
SET IDENTITY_INSERT dm.benh_vien OFF;
GO

